const suppliedSecret = String($json.headers?.['x-n8n-lagos-webhook-secret'] ?? '');
const expectedSecret = 'REPLACE_WITH_SHARED_WEBHOOK_SECRET';
if (expectedSecret !== 'REPLACE_WITH_SHARED_WEBHOOK_SECRET' && suppliedSecret !== expectedSecret) throw new Error('Unauthorized application submission');

const input = $json.body ?? $json;
const required = ['full_name', 'email', 'years_experience', 'skills', 'resume_text'];
const missing = required.filter((key) => input[key] === undefined || input[key] === null || String(input[key]).trim() === '');
if (missing.length) throw new Error(`Missing required fields: ${missing.join(', ')}`);
const hasConsent = input.consent === true || String(input.consent).toLowerCase() === 'true' || String(input.consent).toLowerCase() === 'on';
if (!hasConsent) throw new Error('Consent is required');
const email = String(input.email).trim().toLowerCase();
if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) throw new Error('Invalid email address');
const years = Number(input.years_experience);
if (!Number.isFinite(years) || years < 0 || years > 50) throw new Error('Invalid years of experience');
return [{ json: {
  application_id: $execution.id,
  full_name: String(input.full_name).trim().slice(0, 100),
  email,
  years_experience: years,
  skills: String(input.skills).trim().slice(0, 1200),
  resume_text: String(input.resume_text).trim().slice(0, 6000),
  consent: true,
  role_title: 'People Operations Analyst',
  source: String(input.source ?? 'website'),
  submitted_at: String(input.submitted_at ?? new Date().toISOString()),
  must_have_criteria: [
    'At least 2 years in HR operations, people analytics, or HRIS support',
    'Spreadsheet or data analysis experience',
    'Evidence of process documentation or workflow improvement',
    'Clear written stakeholder communication',
    'Care with confidential employee information and sound judgment about data access'
  ],
  nice_to_have_criteria: ['HRIS or ATS administration', 'Workflow automation exposure', 'Dashboard or reporting experience']
} }];

