parameters.jsCode:
const value = $json.output ?? $json;
const allowed = ['ADVANCE', 'REVIEW', 'DO_NOT_ADVANCE'];
const numericScore = Number(value.score);
const score = Number.isFinite(numericScore) ? Math.max(0, Math.min(100, Math.round(numericScore))) : null;
let recommendation = allowed.includes(value.recommendation) ? value.recommendation : 'REVIEW';
if (score === null || !Array.isArray(value.evidence) || value.evidence.length === 0) recommendation = 'REVIEW';
return [{ json: {
  assessment: {
    score,
    recommendation,
    summary: String(value.summary ?? 'No summary returned'),
    evidence: Array.isArray(value.evidence) ? value.evidence.slice(0, 6) : [],
    gaps: Array.isArray(value.gaps) ? value.gaps.slice(0, 6) : ['Assessment incomplete'],
    interview_questions: Array.isArray(value.interview_questions) ? value.interview_questions.slice(0, 3) : []
  }
} }];

const application = $('Validate Application').item.json;
const assessment = $('Validate Assessment').item.json.assessment;
const approval = $('Recruiter Approval').item.json;
return [{ json: { application_id: application.application_id, candidate_name: application.full_name, candidate_email: application.email, role: application.role_title, ai_score: assessment.score, ai_recommendation: assessment.recommendation, human_decision: 'INVITE', responded_at: approval.respondedAt ?? new Date().toISOString(), workflow_execution_id: $execution.id } }];

